        if not cond: return True
        if "not" in cond: return not self.check(cond["not"])
        if "all" in cond: return all(self.check(c) for c in cond["all"])
        if "any" in cond: return any(self.check(c) for c in cond["any"])
        if "item" in cond: return cond["item"] in self.state["items"]
        if "flag" in cond: return cond["flag"] in self.state["flags"]
        if "rel" in cond:
