                val = self.state["rel"].get(who, 0)
                op, num = rule
                if not {"<": val < num, "<=": val <= num, ">": val > num, ">=": val >= num, "==": val == num}[op]:
                    return False
            return True
        return True

    def apply(self, effects):
        if not effects: return
        for f in effects.get("flags", []): self.state["flags"].add(f)
        for i in effects.get("items", []): 
            if i not in self.state["items"]: self.state["items"].append(i)
